window.BANCO = window.BANCO || {};
window.BANCO.portugues = [
{n:"f",t:"Substantivo",q:"O que é um substantivo próprio?",a:["Uma palavra que indica ação","Um nome específico de pessoa ou lugar, escrito com letra maiúscula","Uma palavra que indica qualidade","Uma palavra que liga duas frases"],c:1,e:"O substantivo próprio dá nome específico a uma pessoa, lugar ou animal, como o seu nome! Por isso ele sempre começa com letra maiúscula."},
{n:"f",t:"Substantivo",q:"Qual destas palavras é um substantivo comum?",a:["Brasil","Maria","cidade","Recife"],c:2,e:"'Cidade' é comum porque serve para qualquer cidade do mundo. Já Brasil, Maria e Recife são nomes específicos, ou seja, substantivos próprios."},
{n:"f",t:"Substantivo",q:"Qual é o coletivo de peixes?",a:["cardume","alcateia","enxame","manada"],c:0,e:"Cardume é o grupo de peixes nadando juntos. Alcateia é de lobos, enxame é de abelhas e manada é de bois ou elefantes."},
{n:"f",t:"Substantivo",q:"Qual é o plural de 'pão'?",a:["pãos","pães","pões","pans"],c:1,e:"Algumas palavras terminadas em -ão fazem o plural em -ães. É o caso de pão → pães, como cão → cães."},
{n:"f",t:"Substantivo",q:"Qual é o feminino de 'leão'?",a:["leona","leã","leoa","leões"],c:2,e:"O feminino de leão é leoa. Cuidado: 'leões' é o plural, não o feminino!"},
{n:"f",t:"Substantivo",q:"Qual destas palavras é um substantivo composto?",a:["chuva","sol","flor","guarda-chuva"],c:3,e:"Guarda-chuva é formado por duas palavras juntas: guarda + chuva. Por isso é composto. As outras têm uma palavra só, então são simples."},
{n:"f",t:"Substantivo",q:"Qual destas palavras é um substantivo primitivo?",a:["pedreiro","pedra","pedreira","pedregulho"],c:1,e:"'Pedra' é primitivo porque não nasceu de nenhuma outra palavra. Pedreiro, pedreira e pedregulho nasceram dela, então são derivados."},
{n:"f",t:"Substantivo",q:"Qual palavra é derivada de 'flor'?",a:["floricultura","folha","fruta","festa"],c:0,e:"Floricultura nasceu da palavra flor: é o lugar onde se vendem flores. As outras só começam com F, mas não vêm de 'flor'."},
{n:"f",t:"Substantivo",q:"Qual é o coletivo de lobos?",a:["manada","rebanho","alcateia","cardume"],c:2,e:"Um grupo de lobos é uma alcateia. Rebanho é de ovelhas, manada é de bois e cardume é de peixes. 🐺"},
{n:"f",t:"Substantivo",q:"Qual destas palavras é um substantivo próprio?",a:["menina","escola","cidade","Brasil"],c:3,e:"Brasil é o nome específico de um país, por isso é próprio e começa com maiúscula. As outras são nomes gerais, ou seja, comuns."},
{n:"m",t:"Substantivo",q:"Na frase 'O menino ganhou um cachorro.', quais palavras são substantivos?",a:["menino e cachorro","o e um","ganhou e cachorro","menino e ganhou"],c:0,e:"Menino e cachorro dão nome a seres, por isso são substantivos. 'Ganhou' é ação (verbo) e 'o' e 'um' são artigos."},
{n:"m",t:"Substantivo",q:"Na frase 'O girassol cresceu no jardim.', a palavra 'girassol' é um substantivo...",a:["primitivo","coletivo","próprio","composto"],c:3,e:"Girassol junta duas palavras: gira + sol. Quando duas palavras formam uma só, o substantivo é composto."},
{n:"m",t:"Substantivo",q:"Na frase 'Maria viajou para Salvador com a irmã.', quantos substantivos próprios há?",a:["um","dois","três","nenhum"],c:1,e:"Maria (nome de pessoa) e Salvador (nome de cidade) são próprios: dois no total. 'Irmã' é comum, pois serve para qualquer irmã."},
{n:"m",t:"Substantivo",q:"Na frase 'O cardume nadava perto da praia.', a palavra 'cardume' é o coletivo de...",a:["pássaros","abelhas","peixes","lobos"],c:2,e:"Cardume é sempre um grupo de peixes. Mesmo sem a palavra 'peixe' aparecer na frase, o coletivo já conta isso para a gente!"},
{n:"m",t:"Substantivo",q:"Se passarmos 'o ator' para o feminino na frase 'O ator ensaiou a peça.', teremos...",a:["a atora","a atriz","a ator","as atrizes"],c:1,e:"O feminino de ator é atriz, uma forma especial. 'As atrizes' está no plural, e a frase pede apenas o feminino no singular."},
{n:"m",t:"Substantivo",q:"Na frase 'A pedreira fica longe da cidade.', a palavra 'pedreira' é derivada de...",a:["pedra","pedreiro","cidade","longe"],c:0,e:"Pedreira é o lugar de onde se tiram pedras, então nasceu da palavra primitiva 'pedra'."},
{n:"m",t:"Substantivo",q:"Complete o plural: 'O coração bate rápido.' → 'Os ___ batem rápido.'",a:["coraçãos","corações","coraçães","coraçones"],c:1,e:"A maioria das palavras em -ão faz plural em -ões: coração → corações, como avião → aviões."},
{n:"m",t:"Substantivo",q:"Na frase 'O beija-flor visitou a flor vermelha.', o substantivo composto é...",a:["flor","vermelha","beija-flor","visitou"],c:2,e:"Beija-flor é formado por duas palavras (beija + flor), por isso é composto. 'Flor' sozinha é um substantivo simples."},
{n:"m",t:"Substantivo",q:"Na frase 'A sapataria abriu cedo.', a palavra 'sapataria' vem do substantivo primitivo...",a:["sapato","sapo","sapataria","cedo"],c:0,e:"Sapataria é a loja de sapatos, então ela nasceu de 'sapato'. Cuidado com 'sapo': parece, mas não tem nada a ver! 😄"},
{n:"m",t:"Substantivo",q:"Na frase 'A frota saiu do porto.', a palavra 'frota' é o coletivo de...",a:["peixes","navios","soldados","pássaros"],c:1,e:"Frota é o conjunto de navios. Grupo de soldados é tropa ou exército, e grupo de pássaros é bando."},
{n:"d",t:"Substantivo",q:"Leia: 'Rosa colheu uma rosa no quintal.' O que podemos dizer sobre as duas palavras 'rosa'?",a:["A primeira é substantivo próprio (nome da menina) e a segunda é comum (a flor)","As duas são substantivos próprios","As duas são substantivos comuns","A primeira é comum e a segunda é próprio"],c:0,e:"A primeira 'Rosa' tem maiúscula porque é o nome da menina: próprio. A segunda é a flor, um nome geral: comum. A mesma palavra pode mudar de tipo!"},
{n:"d",t:"Substantivo",q:"O grupo de jurados que avalia um concurso é chamado de...",a:["plateia","elenco","júri","equipe"],c:2,e:"Júri é o coletivo de jurados. Plateia é o grupo de espectadores e elenco é o grupo de atores."},
{n:"d",t:"Substantivo",q:"Qual é o plural correto de 'guarda-chuva'?",a:["guardas-chuva","guarda-chuvas","guardas-chuvas","guarda-chuva (não muda)"],c:1,e:"Aqui 'guarda' vem do verbo guardar, e verbo não vai para o plural. Só o substantivo 'chuva' muda: guarda-chuvas."},
{n:"d",t:"Substantivo",q:"As palavras 'ferramenta', 'ferreiro' e 'ferrugem' são derivadas de qual palavra primitiva?",a:["ferro","ferramenta","feira","fera"],c:0,e:"Todas nasceram de 'ferro'! O ferreiro trabalha com ferro, a ferramenta é feita de ferro e a ferrugem aparece no ferro velho."},
{n:"d",t:"Substantivo",q:"Qual destas palavras NÃO é um substantivo composto?",a:["passatempo","pontapé","couve-flor","cavalo"],c:3,e:"Cavalo é uma palavra só, simples. Passatempo (passa+tempo), pontapé (ponta+pé) e couve-flor (couve+flor) juntam duas palavras."},
{n:"d",t:"Substantivo",q:"Qual é o coletivo de ilhas?",a:["constelação","arquipélago","cordilheira","coleção"],c:1,e:"Arquipélago é um grupo de ilhas vizinhas. Constelação é grupo de estrelas e cordilheira é grupo de montanhas."},
{n:"d",t:"Substantivo",q:"Complete: 'Lave as ___ antes do lanche.'",a:["mães","mãos","mões","manos"],c:1,e:"O plural de mão é mãos, só acrescenta o S. Cuidado com 'mães', que é o plural de mãe!"},
{n:"d",t:"Substantivo",q:"Na frase 'A menina guardou o livro na mochila.', quantos substantivos há?",a:["dois","quatro","três","cinco"],c:2,e:"São três: menina, livro e mochila. 'Guardou' é verbo e 'a', 'o', 'na' não dão nome a nada."},
{n:"d",t:"Substantivo",q:"Na frase 'À noite, vimos uma constelação brilhante.', a palavra 'constelação' é o coletivo de...",a:["planetas","nuvens","estrelas","luas"],c:2,e:"Constelação é um grupo de estrelas que formam um desenho no céu, como o Cruzeiro do Sul. ⭐"},
{n:"d",t:"Substantivo",q:"Qual é o feminino de 'herói'?",a:["heroína","heróia","heroisa","herói (não muda)"],c:0,e:"O feminino de herói é heroína, uma forma especial que precisa ser memorizada."},
{n:"f",t:"Artigo",q:"Quais são os artigos definidos?",a:["um, uma, uns, umas","ele, ela, eles, elas","de, em, para, com","o, a, os, as"],c:3,e:"Os artigos definidos são o, a, os, as. Eles apontam algo já conhecido, como quando você diz 'o meu caderno'."},
{n:"f",t:"Artigo",q:"Quais são os artigos indefinidos?",a:["o, a, os, as","este, esta, estes, estas","meu, minha, meus, minhas","um, uma, uns, umas"],c:3,e:"Os indefinidos são um, uma, uns, umas. Usamos quando falamos de algo pela primeira vez ou de forma geral: 'vi um gato'."},
{n:"f",t:"Artigo",q:"Na frase 'A bola caiu.', qual palavra é artigo?",a:["bola","caiu","A","nenhuma"],c:2,e:"'A' é o artigo definido que acompanha o substantivo 'bola'. O artigo sempre vem antes do substantivo."},
{n:"f",t:"Artigo",q:"O artigo serve para...",a:["indicar uma ação","acompanhar e determinar o substantivo","ligar duas frases","indicar uma qualidade"],c:1,e:"O artigo anda sempre grudado no substantivo, antes dele, mostrando se falamos de algo conhecido (o, a) ou não (um, uma)."},
{n:"f",t:"Artigo",q:"A palavra 'uma' é um artigo...",a:["definido masculino","indefinido masculino","definido feminino","indefinido feminino"],c:3,e:"'Uma' é indefinido (fala de algo não conhecido) e feminino (combina com palavras femininas): uma boneca, uma ideia."},
{n:"f",t:"Adjetivo",q:"O que é um adjetivo?",a:["Palavra que dá característica ou qualidade ao substantivo","Palavra que dá nome aos seres","Palavra que indica ação","Palavra que substitui o nome"],c:0,e:"O adjetivo conta como o ser é: bonito, alegre, azul. Ele sempre fala de um substantivo, como uma etiqueta que descreve!"},
{n:"f",t:"Adjetivo",q:"Qual destas palavras é um adjetivo?",a:["casa","correr","feliz","menino"],c:2,e:"'Feliz' indica uma qualidade: a criança feliz, o dia feliz. Casa e menino são substantivos, e correr é verbo."},
{n:"f",t:"Adjetivo",q:"Um adjetivo BIFORME é aquele que...",a:["não muda nunca","tem uma forma para o masculino e outra para o feminino","só existe no plural","só acompanha nomes de pessoas"],c:1,e:"Biforme tem duas formas (bi = dois): bonito/bonita, alto/alta. Ele muda conforme o gênero da palavra que acompanha."},
{n:"f",t:"Adjetivo",q:"Um adjetivo UNIFORME é aquele que...",a:["muda de forma no feminino","só existe no masculino","tem várias formas diferentes","tem uma forma só para masculino e feminino"],c:3,e:"Uniforme tem uma única forma (uni = um): menino feliz, menina feliz. A palavra não muda com o gênero."},
{n:"f",t:"Adjetivo",q:"O par 'bonito/bonita' mostra que esse adjetivo é...",a:["uniforme","invariável","biforme","coletivo"],c:2,e:"Como existe 'bonito' para o masculino e 'bonita' para o feminino, são duas formas: biforme!"},
{n:"f",t:"Adjetivo",q:"O adjetivo 'feliz' é...",a:["uniforme","biforme","substantivo","artigo"],c:0,e:"Dizemos 'o menino feliz' e 'a menina feliz': a palavra não muda. Uma forma só = uniforme."},
{n:"f",t:"Adjetivo",q:"O adjetivo 'azul' é...",a:["biforme","uniforme","próprio","composto"],c:1,e:"Falamos 'o carro azul' e 'a bicicleta azul': não existe 'azula'! Como tem uma forma só, é uniforme."},
{n:"f",t:"Adjetivo",q:"O adjetivo 'inteligente' é...",a:["biforme","primitivo","uniforme","definido"],c:2,e:"'O aluno inteligente' e 'a aluna inteligente': mesma forma para os dois gêneros, então é uniforme."},
{n:"f",t:"Adjetivo",q:"O par 'alto/alta' mostra um adjetivo...",a:["uniforme","invariável","indefinido","biforme"],c:3,e:"'Alto' para o masculino e 'alta' para o feminino: duas formas, adjetivo biforme."},
{n:"f",t:"Adjetivo",q:"Em qual lista TODAS as palavras são adjetivos?",a:["bonito, rápido, gentil","mesa, cadeira, sofá","pular, comer, dormir","eu, tu, ele"],c:0,e:"Bonito, rápido e gentil são qualidades que damos aos seres. As outras listas têm substantivos, verbos e pronomes."},
{n:"m",t:"Adjetivo",q:"Na frase 'O gato preguiçoso dormiu o dia todo.', qual palavra é adjetivo?",a:["gato","preguiçoso","dormiu","dia"],c:1,e:"'Preguiçoso' é a característica do gato. Gato e dia são substantivos, e dormiu é a ação (verbo). 🐱"},
{n:"m",t:"Adjetivo",q:"Na frase 'A menina educada cumprimentou a professora.', o adjetivo 'educada' é...",a:["uniforme","invariável","biforme","coletivo"],c:2,e:"Existe 'educado' (menino) e 'educada' (menina): duas formas, então é biforme."},
{n:"m",t:"Adjetivo",q:"Na frase 'O aluno inteligente resolveu o problema.', o adjetivo 'inteligente' é...",a:["uniforme","biforme","substantivo","artigo"],c:0,e:"'Inteligente' fica igual para menino e menina: aluno inteligente, aluna inteligente. Uma forma só = uniforme."},
{n:"m",t:"Adjetivo",q:"Na frase 'O carro veloz venceu a corrida.', qual é o adjetivo e sua classificação?",a:["corrida, biforme","veloz, uniforme","carro, uniforme","venceu, biforme"],c:1,e:"'Veloz' descreve o carro e não muda no feminino: a moto veloz. Por isso é adjetivo uniforme."},
{n:"m",t:"Adjetivo",q:"Na frase 'Moramos numa casa amarela.', o adjetivo 'amarela' é...",a:["uniforme, pois nunca muda","biforme, pois existe amarelo e amarela","substantivo composto","artigo definido"],c:1,e:"Amarelo/amarela: a forma muda com o gênero (muro amarelo, casa amarela), então é biforme."},
{n:"m",t:"Adjetivo",q:"Qual par de frases mostra um adjetivo UNIFORME?",a:["menino alto / menina alta","aluno estudioso / aluna estudiosa","gato bonito / gata bonita","homem gentil / mulher gentil"],c:3,e:"'Gentil' não mudou de uma frase para a outra: homem gentil, mulher gentil. Nos outros pares, o adjetivo trocou a terminação."},
{n:"m",t:"Adjetivo",q:"Na frase 'O bolo doce e macio acabou rapidinho.', quantos adjetivos há?",a:["um","três","dois","nenhum"],c:2,e:"Dois: 'doce' e 'macio', as duas qualidades do bolo. 'Bolo' é substantivo e 'acabou' é verbo."},
{n:"m",t:"Adjetivo",q:"Na frase 'A sopa está quente.', o adjetivo 'quente' é...",a:["biforme","artigo","substantivo","uniforme"],c:3,e:"'Quente' serve para os dois gêneros: o chá quente, a sopa quente. Não existe 'quenta'! Uniforme."},
{n:"m",t:"Adjetivo",q:"Qual adjetivo pode substituir a expressão destacada em 'menino COM CORAGEM'?",a:["corajoso","covarde","medroso","coração"],c:0,e:"'Com coragem' vira o adjetivo 'corajoso': menino corajoso. Covarde e medroso significam o contrário!"},
{n:"m",t:"Adjetivo",q:"Na frase 'A atleta veloz ganhou a medalha dourada.', os adjetivos são...",a:["atleta e medalha","veloz e dourada","ganhou e veloz","medalha e dourada"],c:1,e:"'Veloz' descreve a atleta e 'dourada' descreve a medalha. Atleta e medalha são os substantivos que recebem essas qualidades."},
{n:"d",t:"Adjetivo",q:"Na frase 'A atriz famosa e gentil deu autógrafos.', como se classificam os adjetivos?",a:["os dois são biformes","os dois são uniformes","'famosa' é biforme e 'gentil' é uniforme","'famosa' é uniforme e 'gentil' é biforme"],c:2,e:"'Famosa' muda com o gênero (famoso/famosa): biforme. 'Gentil' fica igual para os dois (ator gentil, atriz gentil): uniforme."},
{n:"d",t:"Adjetivo",q:"Qual destes adjetivos é UNIFORME?",a:["belo","magro","alto","cruel"],c:3,e:"'Cruel' não muda: o vilão cruel, a bruxa cruel. Belo/bela, magro/magra e alto/alta têm duas formas, são biformes."},
{n:"d",t:"Adjetivo",q:"Na frase 'Este é um problema comum entre estudantes.', o adjetivo 'comum' é...",a:["uniforme, pois tem a mesma forma no masculino e no feminino","biforme, pois existe 'comum' e 'comuma'","substantivo derivado","artigo indefinido"],c:0,e:"'Comum' fica igual: um erro comum, uma dúvida comum. 'Comuma' não existe! Por isso é uniforme."},
{n:"d",t:"Adjetivo",q:"Na frase 'O jovem atleta ágil e dedicado treinou muito.', qual adjetivo é BIFORME?",a:["jovem","ágil","dedicado","atleta"],c:2,e:"'Dedicado' tem feminino 'dedicada': biforme. 'Jovem' e 'ágil' ficam iguais nos dois gêneros (uniformes), e 'atleta' é substantivo."},
{n:"d",t:"Adjetivo",q:"O time infantil e o time juvenil disputaram a final. Os adjetivos 'infantil' e 'juvenil' são...",a:["biformes","uniformes","substantivos próprios","locuções adjetivas"],c:1,e:"Equipe infantil, time infantil: as formas não mudam com o gênero. Uma forma só = uniformes."},
{n:"d",t:"Adjetivo",q:"Compare: 'a criança feliz' e 'o homem feliz'. O que isso prova sobre o adjetivo 'feliz'?",a:["Que ele é biforme","Que ele é um substantivo","Que ele é uniforme, pois não muda com o gênero","Que ele está no plural"],c:2,e:"A palavra ficou igualzinha nas duas frases, mesmo trocando o gênero. Essa é a prova de que 'feliz' é uniforme!"},
{n:"d",t:"Adjetivo",q:"Qual destes adjetivos MUDA de forma no feminino?",a:["trabalhador","feliz","simples","veloz"],c:0,e:"Trabalhador vira trabalhadora: biforme. Feliz, simples e veloz ficam iguais nos dois gêneros (uniformes)."},
{n:"d",t:"Adjetivo",q:"Na frase 'A prova estava simples, mas longa.', como se classificam os adjetivos?",a:["'simples' é biforme e 'longa' é uniforme","'simples' é uniforme e 'longa' é biforme","os dois são biformes","os dois são uniformes"],c:1,e:"'Simples' não muda (exercício simples, prova simples): uniforme. 'Longa' tem masculino 'longo': biforme."},
{n:"d",t:"Adjetivo",q:"Em 'O doce sabor da fruta' e 'A fruta doce', a palavra 'doce' é adjetivo nas duas frases. Ela é...",a:["biforme","composta","derivada","uniforme"],c:3,e:"'Doce' fica igual com palavras masculinas e femininas: o bolo doce, a fruta doce. Uniforme!"},
{n:"d",t:"Adjetivo",q:"Qual alternativa traz um adjetivo biforme e um uniforme, nessa ordem?",a:["feliz e triste","bonito e leal","azul e verde","gentil e educado"],c:1,e:"'Bonito' muda (bonito/bonita): biforme. 'Leal' fica igual (amigo leal, amiga leal): uniforme. Ordem certinha!"},
{n:"f",t:"Locução adjetiva",q:"O que é uma locução adjetiva?",a:["Uma expressão com mais de uma palavra que vale por um adjetivo","Um adjetivo com uma palavra só","Um substantivo composto","Um grupo de verbos"],c:0,e:"Locução adjetiva é um grupinho de palavras (geralmente com 'de') que funciona como adjetivo: 'amor de mãe' = amor materno."},
{n:"f",t:"Locução adjetiva",q:"A locução adjetiva 'de mãe' corresponde ao adjetivo...",a:["paterno","materno","fraterno","infantil"],c:1,e:"'De mãe' = materno: amor de mãe é amor materno. Paterno é 'de pai' e fraterno é 'de irmão'."},
{n:"f",t:"Locução adjetiva",q:"A locução adjetiva 'de ouro' corresponde ao adjetivo...",a:["prateado","ferroso","dourado","colorido"],c:2,e:"'De ouro' = dourado (ou áureo): medalha de ouro é medalha dourada. Prateado seria 'de prata'."},
{n:"f",t:"Locução adjetiva",q:"A locução adjetiva 'do campo' corresponde ao adjetivo...",a:["urbano","marinho","escolar","rural"],c:3,e:"'Do campo' = rural: vida do campo é vida rural. Urbano é o contrário: 'da cidade'."},
{n:"f",t:"Locução adjetiva",q:"A locução adjetiva 'de irmão' corresponde ao adjetivo...",a:["fraterno","materno","paterno","filial"],c:0,e:"'De irmão' = fraterno: abraço de irmão é abraço fraterno. Filial é 'de filho'."},
{n:"f",t:"Gêneros textuais",q:"O que é um poema?",a:["Um texto escrito em versos, muitas vezes organizados em estrofes","Um texto que só serve para vender produtos","Um texto escrito sempre em forma de carta","Um texto que conta apenas fatos científicos"],c:0,e:"O poema é escrito em versos (as linhas) que se juntam em estrofes (os blocos). É como uma música escrita no papel! 🎵"},
{n:"f",t:"Gêneros textuais",q:"Cada linha de um poema recebe o nome de:",a:["parágrafo","estrofe","verso","capítulo"],c:2,e:"Cada linha do poema é um verso. Vários versos juntos formam uma estrofe."},
{n:"f",t:"Gêneros textuais",q:"Um conjunto de versos agrupados em um bloco no poema chama-se:",a:["estrofe","rima","título","frase"],c:0,e:"Estrofe é o bloco de versos, separado dos outros por um espaço. É como um 'parágrafo' do poema."},
{n:"f",t:"Gêneros textuais",q:"O texto que conta a história da vida de uma pessoa real, escrito por outra pessoa, é a:",a:["fábula","biografia","receita","notícia"],c:1,e:"Biografia vem de 'bio' (vida) + 'grafia' (escrita): é a escrita da vida de alguém. Quando a própria pessoa escreve, chamamos de autobiografia."},
{n:"f",t:"Gêneros textuais",q:"Qual é a principal finalidade de uma notícia?",a:["Ensinar a fazer um brinquedo","Informar sobre um fato que aconteceu de verdade","Contar uma história de fadas","Fazer o leitor rir com uma piada"],c:1,e:"A notícia informa fatos reais e recentes: o que aconteceu, quando, onde e com quem."},
{n:"f",t:"Gêneros textuais",q:"Na história em quadrinhos, a fala das personagens aparece dentro de:",a:["parênteses","rodapés","balões","tabelas"],c:2,e:"Os balões mostram o que a personagem fala ou pensa. Balão com pontinhos indica pensamento! 💭"},
{n:"f",t:"Gêneros textuais",q:"Palavras que imitam sons, como 'CRASH!' e 'TCHIBUM!', muito usadas em quadrinhos, chamam-se:",a:["rimas","onomatopeias","sinônimos","legendas"],c:1,e:"Onomatopeia é a palavra que imita um som. Em quadrinhos ela aparece bem grande para você 'ouvir' a cena!"},
{n:"f",t:"Gêneros textuais",q:"O texto informativo tem como objetivo principal:",a:["emocionar o leitor com rimas","apresentar informações e explicações sobre um assunto","narrar aventuras de personagens mágicas","dar ordens ao leitor"],c:1,e:"O texto informativo explica um assunto de forma clara e verdadeira, como aqueles textos do livro de Ciências."},
{n:"f",t:"Gêneros textuais",q:"O texto narrativo apresenta, entre outros elementos:",a:["personagens, tempo, lugar e enredo","apenas rimas e versos","somente números e gráficos","apenas balões e desenhos"],c:0,e:"Toda narrativa conta uma história: tem personagens, acontece em um tempo e em um lugar, e possui um enredo (os acontecimentos)."},
{n:"f",t:"Gêneros textuais",q:"A crônica costuma tratar de:",a:["fórmulas matemáticas complicadas","situações do dia a dia, contadas de um jeito leve","apenas guerras antigas","instruções de montagem de móveis"],c:1,e:"A crônica olha para o cotidiano — uma cena no ônibus, uma conversa em casa — e conta isso de um jeito gostoso de ler."},
{n:"m",t:"Gêneros textuais",q:"Leia: 'A chuva chegou de mansinho / molhou o meu quintal / o sapo deu um pulinho / e virou meu carnaval.' Esse texto é um:",a:["texto informativo","poema","aviso","relatório"],c:1,e:"Está escrito em versos e tem rimas (quintal/carnaval, mansinho/pulinho). Isso é característica de poema."},
{n:"m",t:"Gêneros textuais",q:"Leia: 'Nasceu em Salvador, em 1935. Aos 12 anos ganhou seu primeiro violão e, anos depois, tornou-se um dos maiores músicos do país.' Esse trecho é típico de:",a:["uma biografia","uma receita","um poema","uma história em quadrinhos"],c:0,e:"O texto conta a vida de uma pessoa real, em ordem de tempo. Isso é biografia."},
{n:"m",t:"Gêneros textuais",q:"Leia: 'Ontem, por volta das 14h, um cachorro caiu num bueiro na Rua das Flores. Os bombeiros resgataram o animal em 20 minutos.' Esse texto é uma:",a:["fábula","crônica de humor","notícia","biografia"],c:2,e:"O texto informa um fato real, dizendo quando (ontem, 14h), onde (Rua das Flores) e o que aconteceu. É notícia."},
{n:"m",t:"Gêneros textuais",q:"Qual elemento NÃO faz parte de uma história em quadrinhos?",a:["balões de fala","onomatopeias","quadrinhos (vinhetas)","índice remissivo"],c:3,e:"Índice remissivo aparece em livros de estudo, não em HQ. Balões, onomatopeias e quadrinhos são a cara dos quadrinhos!"},
{n:"m",t:"Gêneros textuais",q:"A diferença principal entre notícia e reportagem é que a reportagem:",a:["é sempre mais curta que a notícia","aprofunda o assunto, com mais detalhes, entrevistas e explicações","é inventada, enquanto a notícia é real","não pode ter fotografias"],c:1,e:"A notícia dá o fato rapidinho. A reportagem investiga mais: ouve pessoas, traz dados e explica as causas."},
{n:"m",t:"Gêneros textuais",q:"Em uma biografia, os fatos costumam ser apresentados:",a:["em ordem de tempo, do nascimento em diante","de trás para frente, sempre","em forma de versos e rimas","apenas em balões de fala"],c:0,e:"A biografia normalmente segue a linha do tempo da vida da pessoa: nasceu, cresceu, fez isso e aquilo."},
{n:"m",t:"Gêneros textuais",q:"Leia: 'Todo dia o seu Joaquim senta no banco da praça e conversa com os pombos. Ontem descobri que ele dá nome a cada um deles.' Esse texto tem cara de:",a:["notícia policial","crônica","texto científico","verbete de dicionário"],c:1,e:"É uma cena simples do dia a dia, contada com leveza e um toque de graça. Isso é crônica."},
{n:"m",t:"Gêneros textuais",q:"O título de uma notícia, escrito em letras maiores para chamar a atenção, é chamado de:",a:["manchete","estrofe","legenda","moral"],c:0,e:"A manchete é o título principal da notícia. Ela resume o fato e faz você querer ler o resto. 📰"},
{n:"m",t:"Gêneros textuais",q:"Leia: 'O coração é um músculo que bombeia o sangue para todo o corpo. Ele bate cerca de 100 mil vezes por dia.' Esse texto é:",a:["narrativo","informativo","poético","publicitário"],c:1,e:"O texto explica como algo funciona, com dados reais e sem contar história. É texto informativo."},
{n:"m",t:"Gêneros textuais",q:"Em uma história em quadrinhos, o balão com contorno de nuvenzinhas e bolinhas indica que a personagem está:",a:["gritando","pensando","sussurrando","cantando"],c:1,e:"Balão de nuvenzinha mostra pensamento: a personagem está falando com ela mesma, por dentro. 💭"},
{n:"m",t:"Gêneros textuais",q:"O enredo de um texto narrativo é:",a:["o conjunto dos acontecimentos da história","o lugar onde a história acontece","a pessoa que conta a história","a lista de personagens"],c:0,e:"Enredo é o que acontece na história, do começo ao fim. O lugar é o espaço e quem conta é o narrador."},
{n:"m",t:"Gêneros textuais",q:"Leia: 'Sou pequenina, tenho asas / mas nunca fui borboleta. / Faço zumzum na janela / e me chamam de...'. Além de estar em versos, esse texto brinca com o gênero:",a:["receita","adivinha","bula de remédio","currículo"],c:1,e:"O texto dá pistas e pede que você descubra a resposta — isso é uma adivinha, escrita em versos."},
{n:"m",t:"Gêneros textuais",q:"Numa notícia, as perguntas básicas que o texto responde são:",a:["o que, quem, quando, onde e por quê","apenas quem e quando","somente o que e como","apenas onde e por quê"],c:0,e:"Toda boa notícia responde essas perguntinhas. Assim o leitor entende o fato completo."},
{n:"d",t:"Gêneros textuais",q:"Leia: 'Marina fechou o caderno, olhou pela janela e decidiu: no dia seguinte, contaria tudo para a mãe. Não dormiu direito.' Esse trecho é narrativo porque:",a:["apresenta rimas e versos regulares","explica cientificamente um fenômeno","apresenta uma personagem vivendo acontecimentos em uma sequência de tempo","lista instruções passo a passo"],c:2,e:"Há personagem (Marina), ações em sequência (fechou, olhou, decidiu) e passagem de tempo. Isso é narrar."},
{n:"d",t:"Gêneros textuais",q:"Um texto começa assim: 'Nasci em 1873, em Minas Gerais, e desde criança gostava de máquinas.' Por ser a própria pessoa contando sua vida, esse texto é uma:",a:["biografia","autobiografia","reportagem","crônica"],c:1,e:"Quando a pessoa conta a própria vida, o texto é autobiografia ('auto' = si mesmo). Escrito por outra pessoa, seria biografia."},
{n:"d",t:"Gêneros textuais",q:"Leia dois trechos. I: 'Foram registrados 32 acidentes na rodovia em julho, segundo a Polícia Rodoviária.' II: 'Julho passou e a estrada continuou engolindo desavisados, como se tivesse fome.' Sobre eles é correto afirmar:",a:["I é informativo e objetivo; II usa linguagem figurada, típica de crônica","ambos são notícias com a mesma linguagem","I é um poema e II é um relatório","ambos são textos científicos"],c:0,e:"O trecho I dá dados exatos, sem opinião. O II usa imagem poética ('estrada engolindo', 'com fome'), jeito bem de crônica."},
{n:"d",t:"Gêneros textuais",q:"Em uma reportagem sobre alimentação escolar, o repórter entrevistou nutricionistas, ouviu alunos e mostrou gráficos. Esses recursos servem para:",a:["transformar o texto em poema","aprofundar e comprovar as informações apresentadas","esconder os fatos do leitor","substituir o título do texto"],c:1,e:"Entrevistas e dados dão sustentação ao que a reportagem afirma. É o que a diferencia de uma notícia rapidinha."},
{n:"d",t:"Gêneros textuais",q:"Leia: 'O menino correu. / O vento correu com ele. / Os dois chegaram ofegantes / no fim da tarde.' Sobre esse texto, é correto afirmar que:",a:["é uma notícia, pois narra um fato real com data","é um poema, pois se organiza em versos e usa linguagem figurada","é um texto informativo, pois explica o vento","é uma biografia, pois fala de um menino"],c:1,e:"Está em versos e trata o vento como se corresse igual a uma pessoa — linguagem figurada. Cara de poema. 🍃"},
{n:"d",t:"Gêneros textuais",q:"Numa história em quadrinhos, letras enormes e tremidas de um 'AAAAH!' dentro de um balão pontiagudo indicam:",a:["que a personagem fala baixinho","que a personagem está gritando ou assustada","que a personagem está dormindo","que o narrador está explicando a cena"],c:1,e:"Balão pontiagudo (de explosão) com letras grandes mostra grito ou susto. O desenho do balão também 'fala'!"},
{n:"d",t:"Gêneros textuais",q:"Qual característica é comum ao texto narrativo E à crônica?",a:["ambos apresentam fatos organizados em uma sequência, com personagens","ambos são obrigatoriamente escritos em versos","ambos apresentam gráficos e tabelas","ambos precisam ter moral no final"],c:0,e:"A crônica é um tipo de narrativa curta sobre o cotidiano: também tem personagens e acontecimentos em sequência."},
{n:"d",t:"Gêneros textuais",q:"Um texto traz: subtítulo, fotografia com legenda, depoimento de moradores e explicação de um especialista sobre enchentes. Esse texto é, muito provavelmente:",a:["um poema narrativo","uma reportagem","uma autobiografia","uma história em quadrinhos"],c:1,e:"Depoimentos + especialista + fotos com legenda = reportagem, que investiga o assunto a fundo."},
{n:"d",t:"Gêneros textuais",q:"Leia: 'Dizem que quem conta um conto aumenta um ponto. Meu avô contava o mesmo conto há quarenta anos — e o peixe já estava do tamanho de um sofá.' O humor desse trecho vem de:",a:["um erro de português cometido pelo autor","um exagero que mostra como as histórias crescem quando são recontadas","uma informação científica sobre peixes","uma rima entre as palavras"],c:1,e:"O peixe 'do tamanho de um sofá' é exagero de propósito, para fazer rir. Crônicas adoram esse recurso. 😄"},
{n:"d",t:"Gêneros textuais",q:"O que diferencia um texto informativo de um texto narrativo?",a:["o informativo explica um assunto; o narrativo conta uma história com personagens","o informativo sempre usa rimas; o narrativo, nunca","o informativo é sempre menor que o narrativo","não existe diferença entre eles"],c:0,e:"Informar é explicar como algo é ou funciona. Narrar é contar o que aconteceu com alguém."},
{n:"d",t:"Gêneros textuais",q:"Numa biografia sobre uma cientista, aparece: 'Em 1962, após anos de pesquisa, publicou o estudo que mudaria a medicina.' A expressão 'em 1962, após anos de pesquisa' serve para:",a:["marcar o tempo em que os fatos aconteceram","indicar o lugar da pesquisa","apresentar a opinião do autor","criar rima com a frase seguinte"],c:0,e:"Biografias organizam a vida no tempo. Expressões como essa mostram quando cada fato aconteceu."},
{n:"d",t:"Gêneros textuais",q:"Leia a manchete: 'Chuva forte alaga ruas e deixa 40 famílias desabrigadas no centro'. Essa manchete cumpre bem sua função porque:",a:["usa rimas para ficar bonita","resume o fato principal e desperta o interesse do leitor","conta uma história inventada","dá instruções ao leitor"],c:1,e:"Boa manchete diz o essencial em poucas palavras e faz você querer ler a notícia inteira."},
{n:"f",t:"Interpretação de texto",q:"Leia: 'Tomás acordou cedo, vestiu o uniforme e saiu correndo. Era o primeiro dia de aula do ano.' O que Tomás fez logo depois de acordar?",a:["Tomou café da manhã","Vestiu o uniforme","Foi dormir de novo","Arrumou a mochila"],c:1,e:"O texto diz na ordem: acordou, vestiu o uniforme e saiu correndo. A ação logo depois de acordar foi vestir o uniforme."},
{n:"f",t:"Interpretação de texto",q:"Leia: 'A biblioteca da escola tem 3 mil livros. Às terças-feiras, ela abre até as 18h para os alunos estudarem.' Até que horas a biblioteca abre às terças?",a:["Até as 15h","Até as 17h","Até as 18h","Até as 20h"],c:2,e:"A informação está no próprio texto: às terças-feiras a biblioteca abre até as 18h. 📚"},
{n:"f",t:"Interpretação de texto",q:"Leia: 'Dona Rita cuida de um jardim cheio de girassóis. Toda manhã ela rega as flores antes do café.' Quem cuida do jardim?",a:["Dona Rita","A vizinha","O jardineiro da praça","Ninguém"],c:0,e:"O texto começa dizendo que Dona Rita cuida do jardim. Basta procurar quem pratica a ação."},
{n:"f",t:"Interpretação de texto",q:"Leia: 'O ônibus quebrou no meio da estrada. Os passageiros esperaram duas horas até chegar outro veículo.' Quanto tempo os passageiros esperaram?",a:["Meia hora","Uma hora","Duas horas","O dia inteiro"],c:2,e:"O texto informa direitinho: esperaram duas horas até chegar outro veículo."},
{n:"f",t:"Interpretação de texto",q:"Leia: 'No sábado, choveu tanto que o jogo foi adiado para o domingo.' Por que o jogo foi adiado?",a:["Porque o time não apareceu","Por causa da chuva forte","Porque acabou a luz","Porque o juiz se atrasou"],c:1,e:"A causa está clara no texto: choveu tanto que não deu para jogar. Por isso o jogo passou para domingo."},
{n:"f",t:"Interpretação de texto",q:"Leia: 'Meu avô guarda na gaveta um relógio antigo. Foi presente do bisavô, e ele nunca deixou ninguém consertar.' Onde o avô guarda o relógio?",a:["No armário","Na gaveta","Na mochila","No bolso do casaco"],c:1,e:"O texto diz que o avô guarda o relógio na gaveta. Procurar o lugar é responder 'onde'."},
{n:"f",t:"Interpretação de texto",q:"Leia: 'Os pinguins-imperadores vivem na Antártida. Eles se juntam em grandes grupos para se aquecer no frio extremo.' Por que os pinguins se juntam em grupos?",a:["Para brincar","Para se aquecer","Para caçar peixes","Para dormir em pé"],c:1,e:"O próprio texto explica: eles se juntam para se aquecer no frio extremo. É como um abraço coletivo! 🐧"},
{n:"f",t:"Interpretação de texto",q:"Leia: 'Ana ganhou um cachorro no aniversário. Ela deu o nome de Pipoca, porque o filhote não parava quieto.' Por que o cachorro se chama Pipoca?",a:["Porque ele é amarelo","Porque ele gosta de milho","Porque ele não parava quieto","Porque nasceu numa festa"],c:2,e:"O texto explica o motivo do nome: o filhote pulava sem parar, igual pipoca estourando. 🍿"},
{n:"f",t:"Interpretação de texto",q:"Leia: 'A festa junina da escola será no dia 20, no pátio, a partir das 15h. Haverá quadrilha e barracas de comidas típicas.' Onde será a festa?",a:["No ginásio","No pátio da escola","Na praça do bairro","No salão da igreja"],c:1,e:"O texto informa o lugar: no pátio. Também diz o dia (20) e a hora (15h)."},
{n:"f",t:"Interpretação de texto",q:"Leia: 'Sempre que o sinal toca, Pedro é o último a sair da sala. Ele gosta de guardar tudo com calma.' Como é o jeito de Pedro?",a:["Apressado e distraído","Calmo e organizado","Bravo e impaciente","Medroso e calado"],c:1,e:"O texto mostra que ele guarda tudo com calma e sai por último: um jeito calmo e organizado."},
{n:"m",t:"Interpretação de texto",q:"Leia: 'O céu ficou cor de chumbo. Em minutos, o vento derrubou os guarda-sóis e todo mundo correu para dentro.' A expressão 'céu cor de chumbo' indica que o céu estava:",a:["azul e limpo","cinzento e carregado, sinal de tempestade","alaranjado, como no pôr do sol","estrelado"],c:1,e:"Chumbo é um metal cinza escuro. Dizer que o céu estava cor de chumbo é dizer que estava cinzento, fechado para chuva. ⛈️"},
{n:"m",t:"Interpretação de texto",q:"Leia: 'Lucas treinou todos os dias durante seis meses. Quando finalmente subiu ao palco, suas mãos tremiam, mas ele sorria.' O que se pode concluir sobre Lucas?",a:["Ele estava nervoso, mas feliz por se apresentar","Ele odiava tocar em público","Ele não tinha se preparado","Ele desistiu da apresentação"],c:0,e:"As mãos tremendo mostram nervosismo; o sorriso mostra alegria. Os dois sentimentos aparecem juntos."},
{n:"m",t:"Interpretação de texto",q:"Leia: 'A cidade de Ouro Preto guarda casarões e igrejas do século XVIII. Suas ruas de pedra atraem visitantes do mundo inteiro.' A ideia principal do texto é:",a:["ensinar a fazer casarões","apresentar Ouro Preto como cidade histórica que atrai turistas","contar a vida de um morador","criticar as ruas de pedra"],c:1,e:"O texto todo fala do valor histórico da cidade e da atração de visitantes. Essa é a ideia central."},
{n:"m",t:"Interpretação de texto",q:"Leia: 'Bia entrou em casa pingando, os tênis encharcados, o cabelo grudado no rosto. Nem precisou dizer nada.' O texto sugere que:",a:["Bia tomou banho de piscina","Bia foi pega por uma chuva forte","Bia lavou o carro","Bia estava suando de calor"],c:1,e:"Pingando, tênis encharcados, cabelo grudado: pistas de que ela apanhou chuva no caminho. O texto não diz, mas dá para concluir."},
{n:"m",t:"Interpretação de texto",q:"Leia: 'Quando o professor terminou de falar, a sala inteira aplaudiu. Alguns alunos até se levantaram.' A reação dos alunos mostra que eles:",a:["ficaram entediados","gostaram muito do que ouviram","não entenderam nada","estavam com pressa de sair"],c:1,e:"Aplausos e gente se levantando são sinais de aprovação e entusiasmo. 👏"},
{n:"m",t:"Interpretação de texto",q:"Leia: 'O gato dormia no sofá como se a casa fosse dele. Quando alguém chegava perto, ele apenas abria um olho.' A frase 'como se a casa fosse dele' indica que o gato:",a:["era o dono legal da casa","estava perdido e assustado","agia com total tranquilidade e liberdade","queria fugir pela janela"],c:2,e:"A comparação mostra o jeito folgado e confiante do gato — ele se sentia em casa mesmo. 🐈"},
{n:"m",t:"Interpretação de texto",q:"Leia: 'Faltavam dez minutos para o fim da prova. Rafa ainda não tinha respondido a última questão. Sua caneta parou no ar.' O trecho transmite principalmente uma sensação de:",a:["tédio","tensão","alegria","sono"],c:1,e:"Tempo acabando + questão em branco + caneta parada no ar criam clima de nervosismo, ou seja, tensão."},
{n:"m",t:"Interpretação de texto",q:"Leia: 'Reciclar é importante: uma lata de alumínio reciclada economiza energia suficiente para manter uma televisão ligada por três horas.' O dado sobre a televisão foi usado para:",a:["mostrar de forma concreta o benefício da reciclagem","ensinar a consertar televisões","criticar quem assiste televisão","explicar como fazer latas"],c:0,e:"O autor usa um exemplo do dia a dia para você imaginar o tamanho da economia. Fica mais fácil de entender. ♻️"},
{n:"m",t:"Interpretação de texto",q:"Leia: 'Não era a primeira vez que Duda perdia a chave. Dessa vez, porém, ela estava dentro do bolso o tempo todo.' A palavra 'porém' indica:",a:["uma soma de ideias","uma ideia contrária ao que se esperava","uma explicação de causa","uma conclusão final"],c:1,e:"'Porém' marca oposição: ela costumava perder mesmo, MAS dessa vez a chave estava com ela."},
{n:"m",t:"Interpretação de texto",q:"Leia: 'A professora pediu silêncio três vezes. Na quarta, apenas cruzou os braços e esperou.' A atitude da professora na quarta vez mostra que ela:",a:["desistiu da aula","usou o silêncio dela como forma de chamar atenção","ficou com medo dos alunos","saiu da sala"],c:1,e:"Em vez de falar mais alto, ela parou e esperou. É uma forma silenciosa de dizer 'estou aguardando'."},
{n:"m",t:"Interpretação de texto",q:"Leia: 'O time perdeu de novo. Mesmo assim, a torcida cantou até o último minuto.' A expressão 'mesmo assim' mostra que a torcida:",a:["cantou por causa da derrota","parou de cantar após a derrota","apoiou o time apesar da derrota","não foi ao estádio"],c:2,e:"'Mesmo assim' indica que, apesar do resultado ruim, a torcida continuou apoiando. 💙"},
{n:"m",t:"Interpretação de texto",q:"Leia: 'Toda quarta, seu Antônio abre a oficina às seis da manhã. Diz que gosta do barulho da rua acordando.' O texto revela que seu Antônio:",a:["odeia sua profissão","aprecia a rotina do começo do dia","trabalha apenas à noite","mora longe da oficina"],c:1,e:"Ele acorda cedo por gosto e curte o movimento da rua despertando: sinal de que aprecia essa rotina."},
{n:"d",t:"Interpretação de texto",q:"Leia: 'Clara segurou o convite por um tempo. Leu o nome da amiga, dobrou o papel e guardou no fundo da gaveta. Depois foi assistir televisão como se nada tivesse acontecido.' O comportamento de Clara sugere que ela:",a:["ficou muito animada com o convite","escondeu um incômodo que preferiu não demonstrar","não sabia ler o convite","perdeu o convite sem querer"],c:1,e:"Guardar no fundo da gaveta e fingir naturalidade são pistas de que algo a incomodou, mesmo sem o texto dizer. Isso é ler nas entrelinhas. 🔍"},
{n:"d",t:"Interpretação de texto",q:"Leia: 'A cada ano, o rio some um pouco mais. Onde havia água, hoje há pó. As crianças da vila já não sabem o que é nadar.' O trecho tem como objetivo principal:",a:["ensinar técnicas de natação","alertar sobre o desaparecimento do rio e suas consequências","descrever um passeio divertido","contar a história de uma criança"],c:1,e:"O texto mostra a água virando pó e crianças sem poder nadar: é um alerta sobre a perda do rio."},
{n:"d",t:"Interpretação de texto",q:"Leia: 'Meu irmão diz que não tem medo de nada. Ontem, um trovão fez a janela tremer — e ele apareceu no meu quarto \"só para ver se eu estava bem\".' O humor do trecho está em:",a:["o irmão realmente ser corajoso","o contraste entre o que o irmão diz e o que ele faz","a descrição científica do trovão","a rima entre as palavras"],c:1,e:"Ele jura não ter medo, mas correu para o quarto com a desculpa de cuidar do outro. A contradição é a graça. 😄"},
{n:"d",t:"Interpretação de texto",q:"Leia: 'A sala estava em silêncio absoluto. Só se ouvia o ventilador, o barulho das canetas e, de vez em quando, um suspiro.' A descrição sugere que os alunos estavam:",a:["conversando animadamente","concentrados fazendo uma atividade","saindo para o recreio","assistindo a um filme"],c:1,e:"Silêncio + som de canetas + suspiros formam a cena de uma turma concentrada escrevendo, provavelmente numa prova."},
{n:"d",t:"Interpretação de texto",q:"Leia: 'O prefeito prometeu asfalto novo. Passaram-se três anos e a rua continua a mesma — só as promessas foram repavimentadas.' A ironia do trecho está em:",a:["dizer que a rua ficou perfeita","usar 'repavimentadas' para as promessas, mostrando que só elas foram renovadas","explicar como se faz asfalto","elogiar sinceramente o prefeito"],c:1,e:"O autor brinca: a rua continua ruim, mas as promessas foram 'refeitas'. É uma crítica dita com humor."},
{n:"d",t:"Interpretação de texto",q:"Leia: 'Dizem que a vovó era brava. Eu só me lembro do cheiro de bolo e das mãos ásperas segurando as minhas na travessia da rua.' O narrador demonstra em relação à avó:",a:["medo e distanciamento","carinho, com base em memórias afetivas","total indiferença","raiva pelo passado"],c:1,e:"Cheiro de bolo e mãos protegendo na travessia são lembranças carinhosas. O narrador guarda afeto, não medo. ❤️"},
{n:"d",t:"Interpretação de texto",q:"Leia: 'Estudos indicam que dormir menos de oito horas prejudica a memória de crianças. Mesmo assim, muitos alunos vão à escola com sono.' A relação entre as duas frases é de:",a:["causa e consequência esperadas","contraste entre o que se recomenda e o que acontece na prática","comparação entre duas escolas","sequência de tempo"],c:1,e:"A primeira frase diz o ideal; a segunda mostra a realidade diferente. 'Mesmo assim' marca esse contraste. 😴"},
{n:"d",t:"Interpretação de texto",q:"Leia: 'O menino carregava a mochila como se fosse uma montanha nas costas. Dentro dela, só um caderno e um pote de suco.' O exagero na descrição serve para:",a:["informar o peso exato da mochila","dar ideia do cansaço ou desânimo do menino","explicar o que é uma montanha","ensinar a arrumar a mochila"],c:1,e:"A mochila era leve, então o peso é de cansaço, não de coisas. O exagero mostra o sentimento dele."},
{n:"d",t:"Interpretação de texto",q:"Leia: 'Assim que a chuva parou, o cheiro de terra molhada subiu. A vizinhança inteira abriu as janelas ao mesmo tempo, como se combinado.' A expressão 'como se combinado' indica que:",a:["os vizinhos marcaram a hora por telefone","todos reagiram igual, sem terem combinado nada","ninguém abriu as janelas","a chuva continuou forte"],c:1,e:"'Como se' introduz comparação: pareceu combinado, mas foi uma reação natural e simultânea de todos. 🌧️"},
{n:"d",t:"Interpretação de texto",q:"Leia: 'Toda vez que perdia, Miguel dizia que o jogo era chato. Toda vez que ganhava, dizia que era o melhor jogo do mundo.' O texto revela que Miguel:",a:["avalia o jogo conforme o próprio resultado","conhece muito sobre jogos","nunca gostou de jogar","sempre fala a verdade sobre os jogos"],c:0,e:"A opinião dele muda conforme ganha ou perde: não é o jogo que muda, é o humor dele. 🎮"},
{n:"d",t:"Interpretação de texto",q:"Leia: 'A menina olhou o mar pela primeira vez. Ficou em silêncio, imóvel, os pés fincados na areia — e só então soltou um sorriso enorme.' O silêncio da menina indica:",a:["tristeza profunda","espanto e encantamento diante da novidade","medo da água","cansaço da viagem"],c:1,e:"O silêncio veio do deslumbramento; o sorriso enorme depois confirma o encantamento. 🌊"},
{n:"d",t:"Interpretação de texto",q:"Leia: 'Ele repetiu o mesmo erro na prova. Não por falta de estudo, mas porque leu a pergunta rápido demais.' A informação depois de 'não por falta de estudo' serve para:",a:["afastar uma causa provável e apresentar a causa verdadeira","confirmar que ele não estudou","mudar de assunto","elogiar o desempenho dele"],c:0,e:"O autor descarta uma explicação (não estudou) para apontar a real: pressa na leitura. Ler devagar é meio caminho na prova! 👀"},
{n:"f",t:"Graus do adjetivo",q:"Na frase 'Meu caderno é tão novo quanto o seu', o adjetivo está no grau:",a:["comparativo de igualdade","comparativo de superioridade","superlativo absoluto","comparativo de inferioridade"],c:0,e:"'Tão... quanto' compara duas coisas mostrando que são iguais. Por isso, comparativo de igualdade."},
{n:"f",t:"Graus do adjetivo",q:"Na frase 'Este livro é mais interessante que aquele', o adjetivo está no grau:",a:["comparativo de igualdade","comparativo de superioridade","comparativo de inferioridade","superlativo relativo"],c:1,e:"'Mais... que' mostra que um é superior ao outro naquela qualidade: comparativo de superioridade."},
{n:"f",t:"Graus do adjetivo",q:"Na frase 'O filme é menos divertido que o livro', o adjetivo está no grau:",a:["comparativo de superioridade","superlativo absoluto sintético","comparativo de inferioridade","comparativo de igualdade"],c:2,e:"'Menos... que' indica que um fica abaixo do outro: comparativo de inferioridade."},
{n:"f",t:"Graus do adjetivo",q:"O superlativo absoluto sintético de 'alto' é:",a:["mais alto","altíssimo","muito alto","o mais alto"],c:1,e:"No sintético a intensidade vira uma palavra só, com terminação -íssimo: altíssimo. 'Muito alto' também intensifica, mas usando duas palavras (analítico)."},
{n:"f",t:"Graus do adjetivo",q:"A forma 'muito bonito' é um exemplo de superlativo absoluto:",a:["sintético","analítico","relativo","comparativo"],c:1,e:"Analítico usa duas palavras: 'muito' + adjetivo. Se fosse uma palavra só (bonitíssimo), seria sintético."},
{n:"f",t:"Graus do adjetivo",q:"O superlativo absoluto sintético de 'bom' é:",a:["boníssimo apenas","ótimo","mais bom","bonzão"],c:1,e:"'Bom' tem forma especial: ótimo. É como dizer 'muito bom' em uma palavra só. 👍"},
{n:"f",t:"Graus do adjetivo",q:"O superlativo absoluto sintético de 'mau' é:",a:["péssimo","maisíssimo","malzão","maioral"],c:0,e:"'Mau' vira péssimo, que quer dizer 'muito mau'. Lembre: bom→ótimo, mau→péssimo."},
{n:"f",t:"Graus do adjetivo",q:"Na frase 'Júlia é a aluna mais estudiosa da turma', o adjetivo está no grau:",a:["comparativo de igualdade","superlativo absoluto analítico","superlativo relativo de superioridade","comparativo de inferioridade"],c:2,e:"Ela é comparada a um grupo (a turma) e fica no topo. Por isso, superlativo relativo de superioridade."},
{n:"f",t:"Graus do adjetivo",q:"Na frase 'Pedro é o menos apressado do grupo', o adjetivo está no grau:",a:["superlativo relativo de inferioridade","comparativo de superioridade","superlativo absoluto sintético","comparativo de igualdade"],c:0,e:"Ele é comparado ao grupo e fica na posição mais baixa dessa qualidade: superlativo relativo de inferioridade."},
{n:"f",t:"Graus do adjetivo",q:"Os dois graus do adjetivo estudados são:",a:["masculino e feminino","singular e plural","comparativo e superlativo","primitivo e derivado"],c:2,e:"Os graus mostram intensidade: o comparativo compara dois seres; o superlativo mostra intensidade máxima."},
{n:"f",t:"Graus do adjetivo",q:"O superlativo absoluto sintético de 'fácil' é:",a:["facilzinho","facílimo","mais fácil","o mais fácil"],c:1,e:"Fácil vira facílimo (muito fácil). Repare que perde o 'il' e ganha '-ílimo'."},
{n:"m",t:"Graus do adjetivo",q:"Qual frase apresenta um comparativo de igualdade?",a:["Ana é mais rápida que Bia.","Ana é tão rápida quanto Bia.","Ana é a mais rápida da escola.","Ana é rapidíssima."],c:1,e:"'Tão... quanto' iguala as duas. As outras opções comparam com diferença ou intensificam."},
{n:"m",t:"Graus do adjetivo",q:"Transforme em superlativo absoluto sintético: 'Este exercício é muito difícil.'",a:["Este exercício é o mais difícil.","Este exercício é dificílimo.","Este exercício é mais difícil que o outro.","Este exercício é tão difícil quanto o outro."],c:1,e:"Trocamos 'muito difícil' por uma palavra só: dificílimo. Continua sendo superlativo absoluto, agora sintético."},
{n:"m",t:"Graus do adjetivo",q:"Na frase 'A prova de hoje foi facílima', o adjetivo está no grau:",a:["comparativo de superioridade","superlativo absoluto sintético","superlativo relativo","comparativo de igualdade"],c:1,e:"Terminação -íssimo/-imo sem comparar com ninguém: intensidade máxima, superlativo absoluto sintético."},
{n:"m",t:"Graus do adjetivo",q:"Qual é a diferença entre 'Ela é altíssima' e 'Ela é a mais alta da turma'?",a:["Na primeira, a intensidade é absoluta; na segunda, ela é comparada a um grupo","As duas frases significam exatamente a mesma coisa","A primeira é comparativa e a segunda é absoluta","Nenhuma das duas indica grau"],c:0,e:"'Altíssima' diz que ela é muito alta, sem comparar. 'A mais alta da turma' compara com o grupo (relativo)."},
{n:"m",t:"Graus do adjetivo",q:"Complete no comparativo de inferioridade: 'O trajeto de ônibus é ___ rápido ___ o de metrô.'",a:["mais / que","tão / quanto","menos / que","muito / de"],c:2,e:"Inferioridade usa 'menos... que': o ônibus fica abaixo do metrô em rapidez."},
{n:"m",t:"Graus do adjetivo",q:"Em 'Aquele foi o dia mais feliz da minha vida', o adjetivo 'feliz' está no grau:",a:["superlativo relativo de superioridade","superlativo absoluto sintético","comparativo de igualdade","comparativo de inferioridade"],c:0,e:"O dia é comparado a todos os outros dias da vida e fica em primeiro lugar: relativo de superioridade."},
{n:"m",t:"Graus do adjetivo",q:"O superlativo absoluto sintético de 'pequeno' é:",a:["pequenininho","mínimo","menor","o menor"],c:1,e:"Pequeno tem forma especial: mínimo (muito pequeno). E grande vira máximo!"},
{n:"m",t:"Graus do adjetivo",q:"Qual frase apresenta superlativo absoluto ANALÍTICO?",a:["Ele é fortíssimo.","Ele é o mais forte do time.","Ele é extremamente forte.","Ele é tão forte quanto o irmão."],c:2,e:"Analítico usa palavra auxiliar de intensidade (muito, extremamente) + adjetivo, sem virar uma palavra só."},
{n:"m",t:"Graus do adjetivo",q:"Em 'Meu quarto é tão bagunçado quanto o do meu irmão', o que se conclui?",a:["O quarto do irmão é mais bagunçado","Os dois quartos têm o mesmo nível de bagunça","O meu quarto é menos bagunçado","O meu quarto é o mais bagunçado da casa"],c:1,e:"Comparativo de igualdade indica empate: os dois são igualmente bagunçados. 😅"},
{n:"m",t:"Graus do adjetivo",q:"O superlativo absoluto sintético de 'grande' é:",a:["maior","grandão","máximo","o maior"],c:2,e:"Grande vira máximo. 'Maior' é comparativo (compara dois), não superlativo absoluto."},
{n:"m",t:"Graus do adjetivo",q:"Complete: 'Este livro é ___ interessante ___ aquele' (comparativo de superioridade).",a:["tão / quanto","menos / que","mais / do que","muito / de"],c:2,e:"Superioridade usa 'mais... (do) que'. As duas formas, 'que' e 'do que', estão corretas."},
{n:"m",t:"Graus do adjetivo",q:"Em 'A viagem foi longuíssima', o falante quer dizer que a viagem foi:",a:["um pouco longa","muito longa","mais longa que outra","a mais longa de todas"],c:1,e:"O -íssimo dá intensidade máxima sem comparar: foi MUITO longa."},
{n:"m",t:"Graus do adjetivo",q:"Qual alternativa apresenta um comparativo, e NÃO um superlativo?",a:["Ele é o mais alto da sala.","Ele é altíssimo.","Ele é mais alto que o primo.","Ele é muito alto."],c:2,e:"'Mais alto que o primo' compara dois seres: é comparativo. As outras intensificam ou comparam com um grupo inteiro."},
{n:"d",t:"Graus do adjetivo",q:"Analise: 'Ronaldo é o jogador mais rápido do time' e 'Ronaldo é rapidíssimo'. A diferença de sentido é que:",a:["a primeira o coloca em primeiro lugar dentro de um grupo; a segunda apenas intensifica a qualidade","as duas afirmam que ele é o melhor do time","a primeira intensifica e a segunda compara","não há diferença de sentido"],c:0,e:"Ser 'o mais rápido do time' depende do grupo. Ser 'rapidíssimo' é ser muito rápido, mesmo sem comparar com ninguém. 🏃"},
{n:"d",t:"Graus do adjetivo",q:"O superlativo absoluto sintético de 'pobre' é:",a:["pobríssimo apenas","paupérrimo","mais pobre","o mais pobre"],c:1,e:"'Pobre' tem forma erudita irregular: paupérrimo (do latim pauper). Na fala do dia a dia também se usa pobríssimo, mas a forma clássica cobrada é paupérrimo."},
{n:"d",t:"Graus do adjetivo",q:"Em qual frase o adjetivo NÃO está no grau superlativo?",a:["A sala estava lotadíssima.","Ela foi extremamente gentil comigo.","Este é o exercício mais complicado da lista.","O meu tênis é tão confortável quanto o seu."],c:3,e:"'Tão... quanto' é comparativo de igualdade. Todas as outras indicam intensidade máxima (superlativo)."},
{n:"d",t:"Graus do adjetivo",q:"Leia: 'Foi o dia mais quente do ano, mas nem por isso foi quentíssimo comparado ao deserto.' As duas formas destacadas indicam, respectivamente:",a:["superlativo relativo de superioridade e superlativo absoluto sintético","comparativo de igualdade e comparativo de inferioridade","superlativo absoluto e comparativo de superioridade","comparativo de superioridade e superlativo relativo"],c:0,e:"'O mais quente do ano' compara dentro de um grupo (relativo). 'Quentíssimo' intensifica sem grupo (absoluto sintético)."},
{n:"d",t:"Graus do adjetivo",q:"Qual reescrita mantém o sentido de 'Aquele foi um péssimo filme'?",a:["Aquele foi o pior filme da história do cinema.","Aquele foi um filme muito ruim.","Aquele foi um filme tão ruim quanto o outro.","Aquele foi um filme menos ruim que o outro."],c:1,e:"Péssimo = muito ruim (superlativo absoluto). As outras opções comparam com outros filmes, mudando o sentido."},
{n:"d",t:"Graus do adjetivo",q:"Na frase 'Mariana é a menos falante das irmãs', é correto afirmar que:",a:["Mariana fala mais que todas as irmãs","Mariana é comparada às irmãs e é a que menos fala","Mariana não fala nada","Mariana fala tanto quanto as irmãs"],c:1,e:"Superlativo relativo de inferioridade: dentro do grupo das irmãs, ela ocupa o último lugar em falar — o que não quer dizer que seja calada."},
{n:"d",t:"Graus do adjetivo",q:"Complete corretamente com o superlativo absoluto sintético: 'O bolo da vovó é ___.' (delicioso)",a:["mais delicioso","deliciosíssimo","o mais delicioso","tão delicioso"],c:1,e:"Basta acrescentar -íssimo ao adjetivo: deliciosíssimo, ou seja, muito delicioso. 🍰"},
{n:"d",t:"Graus do adjetivo",q:"Leia: 'Ele não é o mais inteligente da turma, mas é inteligentíssimo.' Essa frase faz sentido porque:",a:["é impossível ser inteligentíssimo sem ser o primeiro da turma","alguém pode ter uma qualidade em grau altíssimo sem ser o primeiro colocado no grupo","o autor cometeu um erro de português","as duas expressões significam a mesma coisa"],c:1,e:"O superlativo absoluto não depende de comparação. Dá para ser muito inteligente e ainda assim não ser o número um. 🧠"},
{n:"d",t:"Graus do adjetivo",q:"O superlativo absoluto sintético de 'amigo' é:",a:["amiguíssimo","amicíssimo","amigão","mais amigo"],c:1,e:"'Amigo' vem do latim amicus, por isso a forma erudita fica amicíssimo."},
{n:"d",t:"Graus do adjetivo",q:"Em 'Aquela foi a decisão mais difícil da minha vida', o grupo com o qual se compara é:",a:["as decisões de outras pessoas","todas as decisões tomadas pelo falante ao longo da vida","apenas duas decisões","nenhum grupo, pois é superlativo absoluto"],c:1,e:"A expressão 'da minha vida' mostra o grupo de comparação: todas as decisões que a pessoa já tomou."},
{n:"d",t:"Graus do adjetivo",q:"Qual frase apresenta ERRO no uso do grau do adjetivo?",a:["Este problema é mais fácil que o anterior.","Ela é a mais gentil de todas.","Meu irmão é mais melhor que eu no videogame.","O dia está quentíssimo."],c:2,e:"'Melhor' já é o comparativo de 'bom', então 'mais melhor' repete a ideia. O certo é 'é melhor que eu'."},
{n:"d",t:"Graus do adjetivo",q:"Leia: 'A estrada estava movimentadíssima, muito mais cheia que na semana passada.' Os graus usados na frase são, na ordem:",a:["superlativo absoluto sintético e comparativo de superioridade","comparativo de igualdade e superlativo relativo","superlativo relativo e comparativo de inferioridade","dois comparativos de superioridade"],c:0,e:"'Movimentadíssima' intensifica (absoluto sintético); 'mais cheia que' compara com outro momento (comparativo de superioridade)."},
{n:"f",t:"Locução adjetiva",q:"A locução adjetiva 'de leite' corresponde ao adjetivo:",a:["lácteo","férreo","áureo","bovino"],c:0,e:"'De leite' = lácteo. Produtos de leite são produtos lácteos, como o queijo e o iogurte. 🥛"},
{n:"f",t:"Locução adjetiva",q:"A locução adjetiva 'de mãe' corresponde ao adjetivo:",a:["paterno","materno","fraterno","filial"],c:1,e:"'De mãe' = materno. Amor de mãe é amor materno. ❤️"},
{n:"f",t:"Locução adjetiva",q:"A locução adjetiva 'de pai' corresponde ao adjetivo:",a:["paterno","materno","fraterno","real"],c:0,e:"'De pai' = paterno. Cuidado paterno é cuidado de pai."},
{n:"f",t:"Locução adjetiva",q:"A locução adjetiva 'de ouro' corresponde ao adjetivo:",a:["prateado","áureo","férreo","bovino"],c:1,e:"'De ouro' = áureo (ou dourado). Uma coroa de ouro é uma coroa áurea. 👑"},
{n:"f",t:"Locução adjetiva",q:"A locução adjetiva 'do mês' corresponde ao adjetivo:",a:["semanal","anual","mensal","diário"],c:2,e:"'Do mês' = mensal. Uma reunião do mês é uma reunião mensal."},
{n:"f",t:"Artigo",q:"Os artigos definidos são:",a:["o, a, os, as","um, uma, uns, umas","de, em, por, para","este, esse, aquele"],c:0,e:"Os definidos (o, a, os, as) indicam algo já conhecido: 'o cachorro' é aquele cachorro que já sabemos qual é."},
{n:"f",t:"Artigo",q:"Os artigos indefinidos são:",a:["o, a, os, as","um, uma, uns, umas","meu, teu, seu","muito, pouco, todo"],c:1,e:"Os indefinidos (um, uma, uns, umas) apresentam algo de forma vaga: 'um cachorro' é um qualquer, não sabemos qual."},
{n:"f",t:"Artigo",q:"Na frase 'A menina comprou um livro', os artigos são, na ordem:",a:["definido e indefinido","indefinido e definido","dois definidos","dois indefinidos"],c:0,e:"'A' é definido (sabemos qual menina) e 'um' é indefinido (um livro qualquer)."},
{n:"f",t:"Adjetivo",q:"Um adjetivo BIFORME é aquele que:",a:["tem uma forma para o masculino e outra para o feminino","tem sempre a mesma forma nos dois gêneros","só existe no plural","nunca acompanha substantivo"],c:0,e:"Biforme = duas formas. Exemplo: bonito (masculino) e bonita (feminino)."},
{n:"m",t:"Locução adjetiva",q:"Na frase 'Recebi uma carta de amor', a locução adjetiva 'de amor' pode ser substituída por:",a:["amável","amorosa","amado","amante"],c:1,e:"'Carta de amor' = carta amorosa. A locução funciona como adjetivo da palavra carta. 💌"},
{n:"m",t:"Locução adjetiva",q:"A locução adjetiva 'de cabelo' corresponde ao adjetivo:",a:["capilar","cardíaco","ocular","dental"],c:0,e:"'De cabelo' = capilar. Por isso existem tratamentos capilares no salão."},
{n:"m",t:"Locução adjetiva",q:"Qual frase apresenta uma locução adjetiva?",a:["O menino correu depressa.","O anel de prata brilhava na vitrine.","Ela chegou cedo em casa.","Nós estudamos bastante ontem."],c:1,e:"'De prata' descreve o anel, funcionando como adjetivo (anel prateado). As outras expressões indicam modo ou tempo."},
{n:"m",t:"Locução adjetiva",q:"A locução adjetiva 'de criança' corresponde ao adjetivo:",a:["juvenil","senil","infantil","adulto"],c:2,e:"'De criança' = infantil. Brincadeira de criança é brincadeira infantil. 🧸"},
{n:"m",t:"Locução adjetiva",q:"Na frase 'O clima da cidade mudou muito', a locução 'da cidade' equivale ao adjetivo:",a:["rural","urbano","marinho","celeste"],c:1,e:"'Da cidade' = urbano. E 'do campo' seria rural, o contrário."},
{n:"m",t:"Artigo",q:"Qual é a diferença entre 'Comprei o livro' e 'Comprei um livro'?",a:["Na primeira, o livro é conhecido; na segunda, é um livro qualquer","Não há diferença nenhuma","Na primeira são vários livros; na segunda, só um","A primeira está errada"],c:0,e:"O artigo definido aponta algo já conhecido; o indefinido apresenta algo novo ou qualquer. 📗"},
{n:"m",t:"Artigo",q:"Na frase 'Os alunos entregaram as tarefas', os artigos estão no:",a:["singular e são indefinidos","plural e são definidos","plural e são indefinidos","singular e são definidos"],c:1,e:"'Os' e 'as' são definidos e estão no plural, concordando com alunos e tarefas."},
{n:"m",t:"Artigo",q:"Em qual frase o artigo indica que já sabemos exatamente de quem se fala?",a:["Vi um cachorro na rua.","Uma menina pediu ajuda.","A professora chegou cedo hoje.","Encontrei uns papéis no chão."],c:2,e:"'A professora' é definido: sabemos qual professora é. Nas outras, os seres são apresentados de forma vaga."},
{n:"m",t:"Adjetivo",q:"Qual adjetivo é UNIFORME (mesma forma para masculino e feminino)?",a:["bonito","feliz","alto","gordo"],c:1,e:"'Feliz' serve para os dois: menino feliz e menina feliz. Já bonito muda para bonita."},
{n:"m",t:"Adjetivo",q:"Assinale a alternativa em que o adjetivo é BIFORME:",a:["inteligente","simples","corajoso","comum"],c:2,e:"Corajoso vira corajosa no feminino: duas formas. Inteligente, simples e comum não mudam."},
{n:"m",t:"Adjetivo",q:"Na expressão 'uma criança educada e gentil', os adjetivos são, respectivamente:",a:["biforme e uniforme","uniforme e biforme","os dois biformes","os dois uniformes"],c:0,e:"'Educada' muda (educado/educada): biforme. 'Gentil' fica igual nos dois gêneros: uniforme."},
{n:"m",t:"Artigo",q:"Na frase 'Uns amigos meus chegaram cedo', o artigo 'uns' é:",a:["definido, plural","indefinido, plural","definido, singular","indefinido, singular"],c:1,e:"'Uns' é a forma plural do indefinido 'um': amigos não identificados exatamente."},
{n:"d",t:"Locução adjetiva",q:"Na frase 'A viagem de trem durou seis horas', a expressão 'de trem':",a:["é locução adjetiva, pois caracteriza a viagem","é um verbo no infinitivo","é um substantivo coletivo","é um artigo definido"],c:0,e:"'De trem' diz que tipo de viagem foi, funcionando como adjetivo do substantivo viagem. 🚆"},
{n:"d",t:"Locução adjetiva",q:"Qual par relaciona corretamente locução adjetiva e adjetivo?",a:["de boi — bovino","de cavalo — canino","de peixe — felino","de gato — suíno"],c:0,e:"'De boi' = bovino. Cavalo é equino, peixe é piscícola, gato é felino e porco é suíno. 🐂"},
{n:"d",t:"Locução adjetiva",q:"Leia: 'O sorriso de anjo daquela criança encantava todo mundo.' A locução adjetiva 'de anjo' equivale a:",a:["angelical","infernal","artificial","glacial"],c:0,e:"'De anjo' = angelical. A locução descreve como era o sorriso. 😇"},
{n:"d",t:"Locução adjetiva",q:"Em qual alternativa a locução adjetiva foi trocada por um adjetivo de sentido DIFERENTE?",a:["água de chuva — água pluvial","dor de estômago — dor gástrica","luz do sol — luz solar","casa de campo — casa urbana"],c:3,e:"'De campo' seria rural ou campestre, não urbana (que é da cidade). As outras trocas estão certas."},
{n:"d",t:"Locução adjetiva",q:"Leia: 'Ele tem um coração de pedra.' Nessa frase, a locução adjetiva 'de pedra' indica que a pessoa é:",a:["muito doente do coração","insensível, dura com os sentimentos alheios","feita de material resistente","muito forte fisicamente"],c:1,e:"É linguagem figurada: coração de pedra = coração duro, insensível. Não é literalmente feito de pedra."},
{n:"d",t:"Locução adjetiva",q:"Na frase 'Comprei um relógio de parede', a locução 'de parede' serve para:",a:["indicar o lugar onde comprei o relógio","especificar o tipo de relógio","indicar quando comprei","substituir o sujeito da frase"],c:1,e:"Existem relógios de pulso, de bolso, de parede... A locução diz qual é o tipo, como um adjetivo faria. 🕰️"},
{n:"d",t:"Artigo",q:"Leia: 'Encontrei uma solução para o problema. A solução era simples.' A troca de 'uma' por 'a' na segunda frase acontece porque:",a:["a solução já foi apresentada, tornando-se conhecida do leitor","a segunda frase está errada","o artigo mudou de gênero","o substantivo mudou de número"],c:0,e:"Primeiro apresentamos algo novo (indefinido); depois de conhecido, usamos o definido. É assim que os textos se organizam! ✍️"},
{n:"d",t:"Artigo",q:"Em qual frase o uso do artigo definido muda o sentido da expressão?",a:["'Comprei o carro que queria' indica um carro específico já conhecido","'Comprei um carro que queria' significa exatamente o mesmo","artigos nunca alteram o sentido","apenas artigos indefinidos alteram o sentido"],c:0,e:"'O carro' aponta um veículo determinado; 'um carro' apresenta um qualquer. Um artiguinho muda bastante coisa!"},
{n:"d",t:"Adjetivo",q:"Leia: 'Aquele professor gentil deu uma explicação clara e objetiva.' Sobre os adjetivos da frase, é correto afirmar:",a:["'gentil' é uniforme; 'clara' e 'objetiva' são biformes","todos os três são uniformes","todos os três são biformes","'gentil' é biforme e os outros são uniformes"],c:0,e:"Gentil não muda no feminino (uniforme). Claro/clara e objetivo/objetiva mudam (biformes)."},
{n:"d",t:"Adjetivo",q:"Qual alternativa apresenta APENAS adjetivos uniformes?",a:["alto, magro, sério","feliz, simples, comum","bonito, calmo, esperto","novo, velho, forte"],c:1,e:"Feliz, simples e comum servem para masculino e feminino sem mudar. Em 'forte' também não muda, mas novo e velho mudam."},
{n:"d",t:"Adjetivo",q:"Na frase 'A menina inteligente resolveu o problema difícil', os adjetivos classificam-se como:",a:["ambos uniformes","ambos biformes","primeiro uniforme, segundo biforme","primeiro biforme, segundo uniforme"],c:0,e:"Inteligente e difícil não mudam de forma no feminino: menino inteligente / menina inteligente. Os dois são uniformes."},
{n:"d",t:"Locução adjetiva",q:"Leia: 'A prova de Português foi tranquila.' A expressão 'de Português':",a:["é locução adjetiva e indica de que tipo era a prova","é um adjetivo simples","é um substantivo coletivo","é um artigo indefinido"],c:0,e:"Ela caracteriza a prova (qual prova? a de Português), funcionando como adjetivo. 📝"},
{n:"d",t:"Artigo",q:"Leia: 'Os alunos chegaram. Uns traziam guarda-chuva; outros, não.' Os termos 'os' e 'uns' são, respectivamente:",a:["artigo definido e artigo indefinido","dois artigos definidos","dois artigos indefinidos","artigo indefinido e artigo definido"],c:0,e:"'Os alunos' aponta a turma conhecida; 'uns' indica uma parte indeterminada dela."},
{n:"d",t:"Adjetivo",q:"Transforme para o feminino: 'Ele é um menino educado e leal.' A forma correta é:",a:["Ela é uma menina educada e leala.","Ela é uma menina educado e leal.","Ela é uma menina educada e leal.","Ela é uma menina educadas e leais."],c:2,e:"'Educado' é biforme e vira educada; 'leal' é uniforme e não muda. Cuidado com a pegadinha 'leala', que não existe!"}
];
